for _ in range(30):
    line = mcp_inspector.stdout.readline()

    if not line:
        break

    print(line.strip())

try:
    if mcp_inspector.poll() is None:
        mcp_inspector.terminate()
        print("Old Inspector stopped")
    else:
        print("Old Inspector already stopped")
except NameError:
    print("No old Inspector process found")

# Stop Feast server
try:
    feast_server.terminate()
    print("Feast server stopped")
except:
    print("Feast server was already stopped")

# Stop MCP Inspector
try:
    mcp_inspector.terminate()
    print("MCP Inspector stopped")
except:
    print("MCP Inspector was already stopped")
